(function(){
  'use strict';
  const E=window.DenominatorEngine,D=window.DenominatorData,$=s=>document.querySelector(s);
  const views=[['overview','01','看汇总'],['strata','02','拆分母'],['standard','03','换权重'],['audit','04','审结论'],['data','05','数据台']];
  const clone=x=>JSON.parse(JSON.stringify(x));
  let dataset=clone(D.cases[0]),weights=null,preset='pooled',view='overview',prediction='',checks=[],conclusion='',history=[],activeLayer=0,timer=null,tourIndex=-1,tourPaused=false,toastTimer=null;
  const issues=[{id:'mix',title:'总表混合了不同构成',note:'先检查两组在各分层的样本占比，避免把人群结构差异直接归因于方案。'},{id:'every',title:'总体方向不能代替每层方向',note:'逐层核对分子与分母，判断“每一类都更好”的说法是否被数据支持。'},{id:'cause',title:'观察到差异，不等于证明原因',note:'分层和统一权重属于描述性比较，还需要研究设计与更多变量支持因果判断。'}];
  const colors=['#426e5f','#b1c891','#6d93a1','#dcc39a','#8e9584','#c3b4be','#8baf77','#b5bbd0','#d4a481','#869f9d','#bfbd86','#a0afbc'];
  const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pct=(x,n=1)=>(x*100).toFixed(n)+'%';
  const pp=(x,n=1)=>(x>0?'+':'')+(x*100).toFixed(n);
  const num=x=>x.toLocaleString('zh-CN');
  const label=g=>g==='A'?dataset.groupA:dataset.groupB;
  const result=()=>E.analyse(dataset.rows,weights===null?undefined:weights);
  function log(action,detail=''){history.push({at:new Date().toISOString(),action,detail});if(history.length>200)history.shift();}
  function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
  function head(en,title,desc,n){return `<div class="page-head"><div><span class="eyebrow">${en}</span><h1>${title}</h1><p>${desc}</p></div><span class="page-num">${n}</span></div>`;}
  function next(text,target,caption){return `<div class="next-row"><span>${text}</span><button class="solid" data-view="${target}">${caption} →</button></div>`;}
  function rateRow(g,s,t){return `<div class="rate-row"><span class="rate-label">${esc(label(g))}</span><div class="rate-track"><div class="rate-fill ${g==='B'?'b':''}" style="width:${100*s/t}%"></div></div><span class="rate-value">${pct(s/t)}</span><span class="rate-count">${num(s)} / ${num(t)} ${esc(dataset.unit)}${esc(dataset.event)}</span></div>`;}
  function sourceBlock(d){return `<div class="source-card"><h3>${esc(d.short)}</h3><span class="badge">${esc(d.kind)}</span><p style="margin-top:12px">${esc(d.source)}</p>${d.links.map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)} ↗</a>`).join('')}<div class="scope">${esc(d.scope)}</div></div>`;}
  function composition(r){return `<div class="composition">${['A','B'].map(g=>`<div><div class="panel-head" style="margin-bottom:0"><b style="font-size:12px">${esc(label(g))}</b><span class="tiny">n = ${num(r.groups[g].total)}</span></div><div class="stack" aria-label="${esc(label(g))}的分层构成">${r.layers.map((l,i)=>`<span title="${esc(l.name)} ${pct(g==='A'?l.a.share:l.b.share)}" style="width:${100*(g==='A'?l.a.share:l.b.share)}%;background:${colors[i]};color:${i%2?'#203d39':'#fffefa'}">${pct(g==='A'?l.a.share:l.b.share,0)}</span>`).join('')}</div></div>`).join('')}</div><div class="legend">${r.layers.map((l,i)=>`<span><i style="background:${colors[i]}"></i>${esc(l.name)}</span>`).join('')}</div>`;}
  function flow(r){
    const h=Math.max(255,60+r.layers.length*49),rightX=850,leftX=192,scale=(h-85)/Math.max(r.groups.A.total,r.groups.B.total),boxH=(h-90)/2;
    // A schematic source-to-strata flow. Width is normalized within each group,
    // and explicitly not an area-accurate or individual-level flow diagram.
    let paths='',nodes='';const ys={A:74,B:h-64};
    r.layers.forEach((l,i)=>{const y=47+i*(h-85)/Math.max(1,r.layers.length-1);['A','B'].forEach(g=>{const share=g==='A'?l.a.share:l.b.share;paths+=`<path d="M${leftX},${ys[g]} C480,${ys[g]} 560,${y} ${rightX},${y}" fill="none" stroke="${g==='A'?'#426e5f':'#dc986b'}" stroke-opacity=".28" stroke-width="${Math.max(1,share*46)}"/>`;});nodes+=`<circle cx="${rightX}" cy="${y}" r="5" fill="${colors[i]}"/><text x="${rightX+17}" y="${y+4}" font-size="12">${esc(l.name)}</text>`;});
    return `<svg class="flow-svg" viewBox="0 0 1030 ${h}" role="img" aria-label="两组样本流向不同分层的示意图，线宽按本组分层占比缩放"><text x="15" y="22" font-size="10" opacity=".6">原始两组</text><text x="866" y="22" font-size="10" opacity=".6">${esc(dataset.stratum)}分层</text>${paths}${nodes}${['A','B'].map(g=>`<rect x="16" y="${ys[g]-24}" width="176" height="48" rx="5" fill="${g==='A'?'#e5eedb':'#f9e8d9'}"/><text x="30" y="${ys[g]-3}" font-size="13">${esc(label(g))}</text><text x="30" y="${ys[g]+14}" font-size="10" opacity=".65">${num(r.groups[g].total)} ${esc(dataset.unit)}</text>`).join('')}</svg>`;
  }
  function overview(){const r=result(),a=r.groups.A,b=r.groups.B;
    const feedback=prediction?`<div class="feedback">${prediction==='need'?'你选择先补充证据。':'已记录你的初始判断。'}接下来拆开分母，看看两组面对的样本结构是否相同。这个选择不计测评分数。</div>`:'';
    return `<section class="hero"><div><span class="eyebrow">THE NUMBER IS NOT THE WHOLE STORY</span><h1>高的那个，<br>就一定更好吗？</h1><p>同一份数据，换一种比较口径，结论可能改变。先看汇总，再亲手拆开藏在百分比后面的分母。</p><span class="badge">${esc(dataset.short)}</span></div><div class="hero-stats">${['A','B'].map(g=>`<div class="hero-stat"><span class="hero-label">${esc(label(g))} · 总体${esc(dataset.event)}率</span><div class="hero-bignum">${(r.groups[g].rate*100).toFixed(1)}<small>%</small></div><span class="hero-count">${num(r.groups[g].success)} / ${num(r.groups[g].total)} ${esc(dataset.unit)}</span></div>`).join('')}</div><div class="hero-bottom"><span>总体差值 A − B <b>${pp(r.rawDiff)} 个百分点</b></span><span>${esc(dataset.kind)} · 分子/分母可核对</span></div></section>
    <div class="grid-two"><section class="panel"><div class="panel-head"><span class="section-label">一条等待核实的结论</span><span class="tag orange">待审</span></div><p class="quote">${esc(dataset.claim)}</p><span class="tiny">${esc(dataset.question)}</span><div class="choices" style="margin-top:12px">${[['A',label('A')+'更好'],['B',label('B')+'更好'],['need','信息还不够，先看分层']].map((p,i)=>`<button class="choice ${prediction===p[0]?'selected':''}" data-predict="${p[0]}" aria-pressed="${prediction===p[0]}"><span>${i+1}</span>${esc(p[1])}</button>`).join('')}</div>${feedback}</section><section class="panel"><div class="panel-head"><h3>百分比后面，是多少？</h3><span class="tiny">RATE = 成功数 / 总数</span></div>${rateRow('A',a.success,a.total)}${rateRow('B',b.success,b.total)}<div class="note">两组总率本身计算无误。需要核实的是：它能支持多大范围的判断？</div><p class="hint" style="margin-top:14px">${esc(dataset.description)}</p><button class="text-link" data-action="sources">核对数据来源与适用范围 ↗</button></section></div>
    <section class="panel flow-panel"><div class="panel-head"><h3>顺着样本，走进分母。</h3><span class="tiny">构成流向示意</span></div>${flow(r)}<div class="flow-mobile">${composition(r)}</div><div class="flow-caption"><span>分层构成示意，不代表个人流转；详细比例可在“拆分母”核对。</span><span>${r.layers.length} 个分层 · ${num(r.n)} ${esc(dataset.unit)}</span></div></section>${next('第一个问题：两组面对的样本，真的一样吗？','strata','拆开分母')}`;
  }
  function strata(){const r=result(),l=r.layers[Math.min(activeLayer,r.layers.length-1)];return `${head('02 / REVEAL THE DENOMINATOR','把一张总表，拆回每一层。','总率是各层比例的加权平均。分层占比不同，会改变汇总结果；先核对样本构成，再读层内差值。','02')}<section class="panel"><div class="panel-head"><h3>两组的样本构成</h3><span class="tiny">条长 = 本组样本占比 · 总和100%</span></div>${composition(r)}<div class="scope">${esc(dataset.background)}</div></section><div class="layer-grid">${r.layers.map((l,i)=>`<section class="layer-card ${i===activeLayer?'selected':''}"><div class="layer-head"><h3>${esc(l.name)}</h3><span class="diff ${l.diff<0?'negative':''}">${pp(l.diff)} <small>pp</small></span></div>${rateRow('A',l.a.success,l.a.total)}${rateRow('B',l.b.success,l.b.total)}<button class="text-link" data-layer="${i}" aria-pressed="${i===activeLayer}">核对这一层的算式 ↗</button></section>`).join('')}</div><section class="formula-panel" aria-live="polite"><span class="eyebrow">打开算式 / ${esc(l.name)}</span><div class="formula">${l.a.success} ÷ ${l.a.total} − ${l.b.success} ÷ ${l.b.total} = <strong>${pp(l.diff)} 个百分点</strong></div><small class="hint">这是层内比例差；不是两组成功人数之差，也不是因果效果。</small></section><div class="feedback ${r.strictReversal?'':'warn'}">${r.strictReversal?'本例出现严格方向反转：每层的差值与总体差值方向相反。':'本例不能概括为“每一层都与总体反向”。分层是检查方法，不是反转保证。'}</div>${next('下一步：如果给两组相同的样本结构，比较会怎样？','standard','统一参考权重')}`;}
  function stdResults(){const r=result();return `<div class="metric-grid"><div class="metric"><small>原始总体差值 / A − B</small><div class="metric-number">${pp(r.rawDiff)} <span>个百分点</span></div><p>保留各组实际样本构成</p></div><div class="metric active"><small>共同权重下 / A − B</small><div class="metric-number" id="standard-gap">${pp(r.stdDiff)} <span>个百分点</span></div><p>${r.directionChange?'与原始总体差值方向不同':'与原始总体差值未发生方向反转'}</p></div></div><section class="panel" style="margin-top:18px"><div class="panel-head"><h3>同一把尺子，重新比较。</h3><span class="tag">只换参考结构</span></div><div class="comparison-row"><span>比较口径</span><span>${esc(label('A'))}</span><span>${esc(label('B'))}</span></div><div class="comparison-row"><span>原始总体</span><b>${pct(r.groups.A.rate)}</b><b>${pct(r.groups.B.rate)}</b></div><div class="comparison-row"><span>共同权重</span><b>${pct(r.standard.A)}</b><b>${pct(r.standard.B)}</b></div><div class="table-wrap" style="margin-top:20px"><table><caption class="sr-only">分层权重、层内比例与加权贡献</caption><thead><tr><th>分层</th><th>共同权重 w</th><th>A 层内率</th><th>B 层内率</th><th>差值贡献</th></tr></thead><tbody>${r.layers.map(l=>`<tr><td>${esc(l.name)}</td><td>${pct(l.weight,2)}</td><td>${pct(l.a.rate)}</td><td>${pct(l.b.rate)}</td><td>${pp(l.gapContribution,2)} pp</td></tr>`).join('')}</tbody></table></div><div class="note">差值贡献 = 共同权重 ×（A层内率 − B层内率）。表内显示已四舍五入，计算使用完整精度。</div></section><div class="formula-panel"><span class="eyebrow">STANDARDIZATION</span><div class="formula">R<sub>A</sub>* = Σ w<sub>k</sub> × r<sub>Ak</sub> &nbsp; · &nbsp; R<sub>B</sub>* = Σ w<sub>k</sub> × r<sub>Bk</sub></div><small class="hint">两组使用同一套非负且总和为1的权重。参考结构不是“真实世界唯一正确结构”，标准化也不自动获得因果解释。</small></div><details class="details"><summary>进一步复核：把原始差值拆成层内项与构成项</summary><p>采用对称分解的代数恒等式。p表示各组实际层占比，r表示层内率。两项相加等于原始总体差值；它们是描述性分解，不能直接命名为“净效果”和“偏差”。</p><div class="formula">层内项 Σ[(p<sub>Ak</sub>+p<sub>Bk</sub>)/2](r<sub>Ak</sub>−r<sub>Bk</sub>) = ${pp(r.decomposition.within,2)} pp<br>构成项 Σ[(r<sub>Ak</sub>+r<sub>Bk</sub>)/2](p<sub>Ak</sub>−p<sub>Bk</sub>) = ${pp(r.decomposition.composition,2)} pp</div><p>合计 ${pp(r.decomposition.within+r.decomposition.composition,2)} pp；数值残差 ${r.decomposition.residual.toExponential(1)}。此处使用实际组占比，与左侧自选参考权重是两种不同计算。</p></details>`;}
  function standard(){const r=result();return `${head('03 / ONE SHARED REFERENCE','只换结构，不改层内比例。','把两组放到同一套参考权重下重算。拖动任意权重，看差值如何变化；原始计数始终保留。','03')}<div class="split-layout"><section class="panel weight-controls"><div class="panel-head"><h3>参考人群结构</h3><span class="tiny">Σw = 1</span></div><div class="preset-grid">${[['pooled','合并样本'],['equal','每层等权'],['A','A组结构'],['B','B组结构']].map(p=>`<button data-preset="${p[0]}" class="${preset===p[0]?'active':''}" aria-pressed="${preset===p[0]}">${p[1]}</button>`).join('')}</div>${r.layers.map((l,i)=>`<div class="weight-item"><div class="weight-top"><label for="weight-${i}">${esc(l.name)}</label><output id="weight-out-${i}" for="weight-${i}">${pct(l.weight,1)}</output></div><input id="weight-${i}" data-weight="${i}" type="range" min="0" max="100" step="1" value="${(weights===null?l.weight*100:weights[i])}" aria-label="${esc(l.name)}的相对权重"><small>滑杆给出相对权重；自动归一化显示占比。</small></div>`).join('')}<div class="note">合并样本权重 = 该层两组总数 ÷ 全部总数。滑杆操作不改写原始数据。</div><div id="weight-error" role="alert"></div></section><div id="std-results" aria-live="polite">${stdResults()}</div></div>${next('数值变化之后，原来的那句话还能成立吗？','audit','审查并改写结论')}`;}
  function suggested(){const r=result();return `在${dataset.short}中，${dataset.groupA}总体${dataset.event}率为${pct(r.groups.A.rate)}，${dataset.groupB}为${pct(r.groups.B.rate)}。各层比较${r.strictReversal?'与总体方向相反':'并非必然与总体反向'}；在本次共同权重下，A−B为${pp(r.stdDiff)}个百分点。该结果只描述这份数据及所选参考结构，不能单独证明因果效果。`;}
  function auditStatus(){return checks.length===3?`<div class="audit-result">已检查三类推断风险。请用你自己的话写出有范围、有口径的结论，再导出报告。</div>`:`<div class="scope">已核对 ${checks.length} / 3 项。勾选表示你完成检查，不代表系统已经测得你的理解水平。</div>`;}
  function audit(){const r=result();return `${head('04 / CLAIM UNDER REVIEW','让结论，配得上证据。','从一句过度概括，走向能被复核的描述。选择你已核对的风险，再写出自己的结论。','04')}<div class="audit-grid"><section class="claim-card"><span class="eyebrow">THE CLAIM / 待审结论</span><p class="quote">${esc(dataset.claim)}</p><p>当前证据：${r.layers.length}个分层、${num(r.n)}${esc(dataset.unit)}。这里只提供汇总计数，没有随机分配或完整的个体背景变量。</p><div class="note" style="color:#c4d1bf;border-color:#5f7c67">一份好报告，应保留原始数据、比较口径、参考权重和结论边界。</div></section><section><div class="checks">${issues.map(i=>`<label class="check-row"><input type="checkbox" data-issue="${i.id}" ${checks.includes(i.id)?'checked':''}><span><b>${i.title}</b><small>${i.note}</small></span></label>`).join('')}</div><div id="audit-status" aria-live="polite">${auditStatus()}</div></section></div><section class="panel editor"><label for="conclusion">你的结论 / 不超过1200字</label><textarea id="conclusion" maxlength="1200" placeholder="写清：这是什么数据？比较用了什么口径？能支持什么判断，还不能说明什么？">${esc(conclusion)}</textarea><div class="editor-footer"><small id="word-count">${conclusion.length} / 1200 · 内容保留到本次关闭页面前</small><div class="actions"><button data-action="suggest">插入参考句式</button><button class="solid" data-action="report">导出取证报告 ↗</button></div></div><div class="note">参考句式来自规则模板，不调用生成式AI；插入后可自行修改。没有真实试用或实验设计时，不写“显著提升”“证明更有效”等结论。</div></section><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>把证据一起带走。</h3><span class="tiny">可复算 · 可追溯</span></div><p class="hint">报告包含原始计数、层内比例、当前权重、原始/标准化差值、检查项及你的结论。另可导出JSON证据包，在“数据台”重新导入复算。</p><div class="actions"><button data-action="json">导出 JSON 证据包</button><button data-view="data">去数据台，换一份数据 →</button></div></section>`;}
  function dataView(){const r=result();return `${head('05 / OPEN THE EVIDENCE','数字可以换，方法要站得住。','查看原始计数，导入自己的两组分层数据，或重新导入JSON证据包复算。所有处理在本机浏览器完成。','05')}<div class="data-meta"><div><span>样本总量</span><b>${num(r.n)}</b></div><div><span>共同分层</span><b>${r.layers.length}</b></div><div><span>输入校验标识 · 非密码学签名</span><b style="font:12px/2 Consolas">${E.fingerprint(dataset.rows)}</b></div></div><section class="panel"><div class="panel-head"><h3>原始计数</h3><div class="actions"><button data-action="csv">下载当前 CSV</button><button data-action="json">导出 JSON</button></div></div><div class="table-wrap"><table><caption class="sr-only">原始分层数据</caption><thead><tr><th>分层</th><th>组别</th><th>${esc(dataset.event)}数</th><th>总数（分母）</th><th>${esc(dataset.event)}率</th></tr></thead><tbody>${dataset.rows.map(row=>`<tr><td>${esc(row.stratum)}</td><td>${esc(label(row.group))}</td><td class="numeric">${num(row.success)}</td><td class="numeric">${num(row.total)}</td><td>${pct(row.success/row.total,2)}</td></tr>`).join('')}</tbody></table></div><p class="note">${esc(dataset.source)}</p></section><div class="grid-two"><section class="panel"><div class="panel-head"><h3>带入你的数据</h3><label class="file-button">读取 CSV 文件<input type="file" id="csv-file" accept=".csv,text/csv" aria-label="读取CSV文件"></label></div><p class="hint">首行固定为 stratum,group,success,total。每层A/B各一行；成功数≤总数；分母必须为正。支持1—12层，字段可用英文引号包围。</p><div class="field"><label for="custom-source">数据来源与适用范围（导入前必填）</label><input id="custom-source" type="text" maxlength="300" placeholder="例如：某公开统计表的完整网址、年份、范围；或明确标为自建合成数据"></div><label class="sr-only" for="csv-editor">CSV数据编辑器</label><textarea class="code" id="csv-editor" spellcheck="false">${esc(E.csv(dataset.rows).replace(/^\uFEFF/,''))}</textarea><div class="actions" style="margin-top:12px"><button class="solid" data-action="apply-csv">校验并载入数据</button></div><div id="data-error" role="alert"></div><p class="note">载入后建立“自定义数据”案例，并清空当前判断、权重和结论。请不要导入个人身份信息或未经授权的数据。</p></section><section class="panel"><div class="panel-head"><h3>重新打开证据</h3><span class="badge">JSON REPLAY</span></div><p class="hint">导入本作品导出的JSON：校验结构与输入标识，重新计算结果。文件内的结果字段不会直接当成计算答案。</p><label class="file-button">选择 JSON 证据包<input type="file" id="json-file" accept=".json,application/json" aria-label="重新导入JSON证据包"></label><div class="scope">复算证明输入与公式的计算一致性，不证明数据来源真实、没有遗漏变量，或报告作者身份。</div><div id="json-error" role="alert"></div><details class="details"><summary>计算方法与边界</summary><p>原始总率 = 各层成功数合计 / 总数合计。层内率 = 该层成功数 / 该层总数。共同权重下的标准化率 = 各层率 × 同一参考权重后求和。</p><p>本作品不进行显著性检验、置信区间估计或因果识别，不把标准化率解释成调整后因果效应。对零分母和缺失组别采取拒绝载入，而不是补零。</p></details><button class="text-link" data-action="sources">查看全部来源和方法 ↗</button></section></div>${next('从熟悉的两层案例，到真实历史表格，再到你自己的数据。','overview','回到比较起点')}`;}
  function render(){
    $('#nav').innerHTML=views.map(v=>`<button data-view="${v[0]}" class="${view===v[0]?'active':''}" ${view===v[0]?'aria-current="step"':''}><span>${v[1]}</span><b>${v[2]}</b></button>`).join('');
    $('#view-label').textContent=views.find(v=>v[0]===view)[2];
    $('#dataset-select').innerHTML=D.cases.map(d=>`<option value="${d.id}">${esc(d.title)}</option>`).join('')+(dataset.id==='custom'?'<option value="custom">自定义数据 / 本机载入</option>':'');
    $('#dataset-select').value=dataset.id;$('#dataset-kind').textContent=dataset.kind;$('#dataset-note').textContent=dataset.id==='berkeley'?'历史范围：1973年 · 六个院系':dataset.id==='custom'?'用户载入数据 · 来源待自行核实':'合成数据不代表真实效果';
    $('#main').innerHTML=({overview,strata,standard,audit,data:dataView}[view])();
  }
  function navigate(v,options={}){if(!views.some(x=>x[0]===v))return;view=v;render();if(!options.silent){log('切换步骤',v);window.scrollTo(0,0);try{window.history.replaceState(null,'','#'+v);}catch{}}}
  function loadCase(id){const d=D.cases.find(x=>x.id===id);if(!d)return;dataset=clone(d);weights=null;preset='pooled';prediction='';checks=[];conclusion='';activeLayer=0;history=[];log('载入案例',dataset.id);render();}
  function applyPreset(p){const r=E.analyse(dataset.rows);preset=p;weights=p==='equal'?r.layers.map(()=>1):p==='A'?r.layers.map(l=>l.a.share*100):p==='B'?r.layers.map(l=>l.b.share*100):null;log('设置共同权重',p);render();}
  function updateWeight(i,value){const r=result();const previous=weights===null?r.layers.map(l=>l.weight*100):weights.slice();const candidate=previous.slice();candidate[i]=Number(value);
    try{E.analyse(dataset.rows,candidate);}catch(err){$('#weight-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;$('#weight-'+i).value=previous[i];return;}
    weights=candidate;preset='custom';$('#weight-error').textContent='';$('#std-results').innerHTML=stdResults();const now=result();now.layers.forEach((l,k)=>$('#weight-out-'+k).textContent=pct(l.weight,1));document.querySelectorAll('[data-preset]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});
  }
  function makePayload(){return {format:'denominator-evidence',version:1,applicationVersion:'1.0.0',exportedAt:new Date().toISOString(),dataset:clone(dataset),fingerprint:E.fingerprint(dataset.rows),reference:{preset,weights:result().weights},prediction,checks:checks.slice(),conclusion,computed:result(),actions:history.slice(),limitations:'描述性比较；非因果识别、非显著性检验；合成案例不是实际效果，输入标识不是来源真实性或作者身份认证。'};}
  function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('已发起下载，请选择E盘项目目录保存。');}
  function report(){log('导出报告',dataset.id);const p=makePayload(),r=p.computed;const text=`# 看见分母 · 数据比较取证报告\n\n导出时间：${p.exportedAt}\n作品版本：${p.applicationVersion}\n数据标识：${p.fingerprint}（非密码学签名）\n\n## 1. 数据与范围\n\n案例：${dataset.title}\n性质：${dataset.kind}\n来源：${dataset.source}\n范围：${dataset.scope}\n${dataset.links.map(l=>l.label+'：'+l.url).join('\n')}\n\n## 2. 原始计数\n\n| 分层 | 组别 | 成功数 | 总数 | 比例 |\n| --- | --- | ---: | ---: | ---: |\n${r.rows.map(row=>`| ${row.stratum.replaceAll('|','／')} | ${label(row.group)} | ${row.success} | ${row.total} | ${pct(row.success/row.total,3)} |`).join('\n')}\n\n## 3. 比较结果\n\n${label('A')}总体：${r.groups.A.success}/${r.groups.A.total} = ${pct(r.groups.A.rate,3)}\n${label('B')}总体：${r.groups.B.success}/${r.groups.B.total} = ${pct(r.groups.B.rate,3)}\n原始总体差值 A−B：${pp(r.rawDiff,3)} 个百分点\n共同权重下 A：${pct(r.standard.A,3)}；B：${pct(r.standard.B,3)}\n标准化差值 A−B：${pp(r.stdDiff,3)} 个百分点\n\n参考权重设置：${preset}\n${r.layers.map(l=>`${l.name}：${pct(l.weight,5)}；层内差值 ${pp(l.diff,3)} pp`).join('\n')}\n\n层内项（对称恒等分解）：${pp(r.decomposition.within,3)} pp\n构成项（对称恒等分解）：${pp(r.decomposition.composition,3)} pp\n恒等分解使用各组实际层占比，与自选共同权重不同。上述各项不是因果效应。\n\n## 4. 检查与结论\n\n初始判断：${prediction||'未选择'}\n${issues.map(i=>`- [${checks.includes(i.id)?'x':' '}] ${i.title}`).join('\n')}\n\n本人填写的结论：\n${conclusion.trim()||'尚未填写，不自动生成或冒充本人结论。'}\n\n## 5. 解释边界\n\n${p.limitations}\n结果使用完整精度计算，显示数字经过四舍五入。表格不包含个体背景变量，不能据此证明歧视或因果效果存在或不存在。\n\n## 6. 本次操作记录\n\n${history.map(h=>`${h.at} | ${h.action} | ${h.detail}`).join('\n')}\n\n操作记录是本浏览器会话的功能记录，不是教学效果或用户研究证据。\n`;
    download('看见分母_取证报告.md',text,'text/markdown;charset=utf-8');
  }
  function importPayload(raw){
    if(!raw||raw.format!=='denominator-evidence'||raw.version!==1||!raw.dataset)throw new Error('不是支持的看见分母v1证据包。');
    const d=raw.dataset,rows=E.validateRows(d.rows);if(raw.fingerprint!==E.fingerprint(rows))throw new Error('原始计数与输入标识不一致，未载入。');
    const known=D.cases.find(c=>c.id===d.id);let next;
    if(known){if(JSON.stringify(rows)!==JSON.stringify(known.rows))throw new Error('内置案例的数据已被更改，请通过自定义CSV明确标注后载入。');next=clone(known);}
    else{next=customDataset(rows,typeof d.source==='string'?d.source:'导入文件提供的自定义数据，来源待核实。');}
    const w=raw.reference?.weights;if(!Array.isArray(w))throw new Error('证据包缺少参考权重。');const verified=E.analyse(rows,w);
    if(typeof raw.conclusion!=='string'||raw.conclusion.length>1200)throw new Error('结论字段须为不超过1200字的文本。');
    if(!Array.isArray(raw.checks)||raw.checks.length>3||raw.checks.some(x=>!issues.some(i=>i.id===x))||new Set(raw.checks).size!==raw.checks.length)throw new Error('检查项格式无效。');
    if(!['','A','B','need'].includes(raw.prediction))throw new Error('初始判断字段无效。');
    // Imported history and computed values are intentionally ignored.
    dataset=next;weights=verified.weights.map(x=>x*100);preset='replay';conclusion=raw.conclusion;checks=raw.checks.slice();prediction=raw.prediction;activeLayer=0;history=[];log('导入JSON并重新计算','未信任文件中的computed或actions字段');navigate('standard');toast('已根据原始计数与权重复算，未采用文件内的结果字段。');
  }
  function customDataset(rows,source){if(typeof source!=='string'||source.trim().length<4||source.length>300)throw new Error('请填写4—300字的数据来源与适用范围。');return {id:'custom',title:'自定义两组分层比较',short:'自定义数据',kind:'用户载入 · 来源待自行核实',event:'成功',unit:'条记录',groupA:'组 A',groupB:'组 B',stratum:'条件',claim:'某组总体成功率更高，所以它在每一层都更好，并且是方案本身造成的。',question:'这份数据能支持哪一种判断？',description:'本机载入的分层计数；真实性、采集方式与适用范围由数据提供者核实。',source:source.trim(),links:[],rows,background:'请确认分层条件的定义和时间顺序。分层不能自动消除选择机制、遗漏变量或测量误差。',scope:'自定义数据的描述性比较，不进行因果识别或显著性检验。'};}
  const tourSteps=[
    {v:'overview',title:'01 / 看见比例背后的分母',copy:'这是240名虚构参与者的教学案例。A总体52.5%，B总体77.5%。总率计算正确，但是否能推出B对每类学生都更有效？'},
    {v:'strata',title:'02 / 原来，两组面对的起点不同',copy:'A有83.3%来自基础起点，B有83.3%来自进阶起点。把总表拆开，两层中A都高5个百分点。',before:()=>{activeLayer=0;}},
    {v:'strata',title:'03 / 一行算式，可逐项核对',copy:'基础层：45除以100，减去8除以20，得到正5个百分点。总体差值却是负25个百分点。分母结构足以改变汇总方向。',before:()=>{activeLayer=0;}},
    {v:'standard',title:'04 / 给两组同一套参考权重',copy:'使用两层各一半的共同权重。A变为67.5%，B变为62.5%。没有修改任何层内成功率，只重新组合参考结构。',before:()=>{weights=null;preset='pooled';}},
    {v:'standard',title:'05 / 换参考结构，观察结果',copy:'把基础层相对权重调到80，进阶层20。两组标准化率一起改变；本例每层差值都是5个百分点，所以共同权重下的差值仍是5个百分点。',before:()=>{weights=[80,20];preset='custom';}},
    {v:'audit',title:'06 / 改写比猜答案更重要',copy:'逐项检查样本混合、过度概括和因果跳跃。用自己的话写出数据范围、比较口径和证据边界，再导出可复算报告。'},
    {v:'data',title:'07 / 打开数据，接受复核',copy:'原始计数可下载；自己的CSV会被严格校验。JSON复算重新计算原始计数与权重，不直接信任导入文件中的计算结果。'},
    {v:'strata',title:'08 / 从合成案例迁移到真实历史数据',copy:'切换到R官方伯克利数据：1973年六个院系，4526份申请。层内方向并不全部相同，不能说每层都发生反转，更不能据此证明歧视存在或不存在。',before:()=>{loadCase('berkeley');}},
    {v:'overview',title:'09 / 数据不变，判断更谨慎',copy:'再看一次：总体44.5%与30.4%描述了这份历史表。分层、共同权重和证据边界，帮助我们避免把一个总率说成所有人的故事。'}
  ];
  function showTourStep(i){if(i<0||i>=tourSteps.length){endTour();return;}tourIndex=i;const s=tourSteps[i];s.before?.();navigate(s.v,{silent:true});$('#tourbar').hidden=false;document.body.classList.add('touring');$('#tour-title').textContent=s.title;$('#tour-copy').textContent=s.copy;$('#tour-count').textContent=`${i+1} / ${tourSteps.length}`;window.scrollTo(0,0);if(i===2)setTimeout(()=>$('.formula-panel')?.scrollIntoView({block:'center'}),100);}
  function scheduleTour(){clearInterval(timer);if(!tourPaused)timer=setInterval(()=>showTourStep(tourIndex+1),13000);}
  function startTour(){endTour();loadCase('learning');tourPaused=false;$('#tourbar [data-action=tour-pause]').textContent='暂停';showTourStep(0);scheduleTour();}
  function endTour(){clearInterval(timer);timer=null;tourIndex=-1;$('#tourbar').hidden=true;document.body.classList.remove('touring');}
  document.addEventListener('click',e=>{
    const b=e.target.closest('button,a.brand');if(!b)return;
    if(b.matches('a.brand')){e.preventDefault();navigate('overview');return;}
    if(b.dataset.view){navigate(b.dataset.view);return;}
    if(b.dataset.predict){prediction=b.dataset.predict;log('初始判断',prediction);render();return;}
    if(b.dataset.layer!==undefined){activeLayer=Number(b.dataset.layer);log('核对层内算式',dataset.rows[activeLayer*2]?.stratum||String(activeLayer));render();$('.formula-panel')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
    if(b.dataset.preset){applyPreset(b.dataset.preset);return;}
    const action=b.dataset.action;
    if(action==='sources'){$('#source-content').innerHTML=(dataset.id==='custom'?sourceBlock(dataset):'')+D.cases.map(sourceBlock).join('')+'<div class="source-card"><h3>方法与原创范围</h3><p>成功率、加权平均与辛普森悖论属于已有统计知识。作品贡献在于构成追踪、共同权重操作、结论审查与可复算报告的交互整合；不声称统计理论首创。计算逻辑与界面代码随离线包提供。</p><p>合成案例与公开历史数据始终分别标记；不使用AI在线推断，不上传数据。自动导览会重置并切换案例。</p></div>';$('#sources-dialog').showModal();}
    if(action==='close-dialog')$('#sources-dialog').close();
    if(action==='reset'){endTour();loadCase(dataset.id==='custom'?'learning':dataset.id);navigate('overview');toast('已重置当前实验。');}
    if(action==='report')report();
    if(action==='json'){log('导出JSON证据',dataset.id);download('看见分母_证据包.json',JSON.stringify(makePayload(),null,2),'application/json;charset=utf-8');}
    if(action==='csv')download('看见分母_原始计数.csv',E.csv(dataset.rows),'text/csv;charset=utf-8');
    if(action==='suggest'){conclusion=suggested();$('#conclusion').value=conclusion;$('#word-count').textContent=`${conclusion.length} / 1200 · 参考模板，可修改`;log('插入参考句式','固定模板，非生成式AI');}
    if(action==='apply-csv'){try{const rows=E.parseCSV($('#csv-editor').value),d=customDataset(rows,$('#custom-source').value);dataset=d;weights=null;preset='pooled';prediction='';checks=[];conclusion='';activeLayer=0;history=[];log('载入自定义CSV',E.fingerprint(rows));navigate('overview');toast('已通过校验并载入，自定义数据来源需自行核实。');}catch(err){$('#data-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}}
    if(action==='tour')startTour();if(action==='tour-end')endTour();if(action==='tour-prev'){showTourStep(Math.max(0,tourIndex-1));scheduleTour();}if(action==='tour-next'){showTourStep(tourIndex+1);if(tourIndex>=0)scheduleTour();}if(action==='tour-pause'){tourPaused=!tourPaused;b.textContent=tourPaused?'继续':'暂停';scheduleTour();}
  });
  document.addEventListener('input',e=>{const el=e.target;if(el.dataset.weight!==undefined)updateWeight(Number(el.dataset.weight),el.value);if(el.id==='conclusion'){conclusion=el.value;$('#word-count').textContent=`${conclusion.length} / 1200 · 内容保留到本次关闭页面前`;}});
  document.addEventListener('change',async e=>{const el=e.target;
    if(el.id==='dataset-select'){if(el.value==='custom')return;endTour();loadCase(el.value);navigate(view);}
    if(el.dataset.weight!==undefined)log('调整共同权重',JSON.stringify(result().weights));
    if(el.dataset.issue){checks=el.checked?[...new Set([...checks,el.dataset.issue])]:checks.filter(x=>x!==el.dataset.issue);log('核对推断风险',el.dataset.issue+':'+el.checked);$('#audit-status').innerHTML=auditStatus();}
    if(el.id==='csv-file'){const f=el.files?.[0];if(!f)return;if(f.size>200000){$('#data-error').innerHTML='<div class="error">CSV文件超过200KB。</div>';return;}$('#csv-editor').value=await f.text();toast('文件已读取，填写来源后点击校验载入。');}
    if(el.id==='json-file'){try{const f=el.files?.[0];if(!f)return;if(f.size>300000)throw new Error('JSON文件超过300KB。');importPayload(JSON.parse(await f.text()));}catch(err){$('#json-error').innerHTML=`<div class="error">${esc(err.message)}</div>`;}}
  });
  window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(views.some(x=>x[0]===v))navigate(v,{silent:true});});
  window.DenominatorApp={getSnapshot:makePayload,loadCase,goView:navigate,startTour,endTour,goTourStep:showTourStep,pauseTour:()=>{tourPaused=true;scheduleTour();$('#tourbar [data-action=tour-pause]').textContent='继续';},importPayload};
  log('打开作品','learning');const initial=location.hash.slice(1);if(views.some(v=>v[0]===initial))view=initial;render();
})();
